BEGIN;

CREATE TABLE IF NOT EXISTS forge_resource_policies (id BIGSERIAL PRIMARY KEY,scope_type TEXT NOT NULL CHECK (scope_type IN ('TENANT','PROJECT')),tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,plan_version_id TEXT,effective_version BIGINT NOT NULL,cpu_ms_limit BIGINT NOT NULL DEFAULT 0 CHECK (cpu_ms_limit >= 0),concurrency_limit INTEGER NOT NULL DEFAULT 1 CHECK (concurrency_limit >= 0),job_count_limit INTEGER NOT NULL DEFAULT 0 CHECK (job_count_limit >= 0),queue_weight INTEGER NOT NULL DEFAULT 1 CHECK (queue_weight BETWEEN 1 AND 1000),priority_class INTEGER NOT NULL DEFAULT 100 CHECK (priority_class BETWEEN 0 AND 100000),burst_allowance INTEGER NOT NULL DEFAULT 0 CHECK (burst_allowance >= 0),aging_seconds INTEGER NOT NULL DEFAULT 60 CHECK (aging_seconds BETWEEN 1 AND 86400),max_reservation_seconds INTEGER NOT NULL DEFAULT 3600 CHECK (max_reservation_seconds BETWEEN 10 AND 86400),emergency_throttle BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK ((scope_type='TENANT' AND project_id IS NULL) OR (scope_type='PROJECT' AND project_id IS NOT NULL)),UNIQUE(scope_type,tenant_id,project_id,effective_version));
CREATE UNIQUE INDEX IF NOT EXISTS forge_resource_policy_active_uq ON forge_resource_policies(scope_type,tenant_id,COALESCE(project_id,'')) WHERE active;
CREATE INDEX IF NOT EXISTS forge_resource_policy_lookup_idx ON forge_resource_policies(tenant_id,project_id,active,effective_version DESC);
CREATE TABLE IF NOT EXISTS forge_resource_policy_history (id BIGSERIAL PRIMARY KEY,policy_id BIGINT NOT NULL REFERENCES forge_resource_policies(id) ON DELETE RESTRICT,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,effective_version BIGINT NOT NULL,snapshot JSONB NOT NULL,actor TEXT NOT NULL,reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_resource_reservations (reservation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,job_id TEXT NOT NULL REFERENCES forge_jobs(id) ON DELETE RESTRICT,attempt INTEGER NOT NULL CHECK (attempt > 0),cpu_ms BIGINT NOT NULL DEFAULT 0 CHECK (cpu_ms >= 0),concurrency_units INTEGER NOT NULL DEFAULT 1 CHECK (concurrency_units > 0),plan_version_id TEXT,tenant_policy_version BIGINT,project_policy_version BIGINT,status TEXT NOT NULL DEFAULT 'HELD' CHECK (status IN ('HELD','COMMITTED','RELEASED','EXPIRED')),reserved_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL,released_at TIMESTAMPTZ,committed_at TIMESTAMPTZ,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,UNIQUE(job_id,attempt));
CREATE INDEX IF NOT EXISTS forge_resource_reservation_scope_idx ON forge_resource_reservations(tenant_id,project_id,status,expires_at);
CREATE INDEX IF NOT EXISTS forge_resource_reservation_job_idx ON forge_resource_reservations(job_id,status);
CREATE TABLE IF NOT EXISTS forge_resource_usage_windows (tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id TEXT NOT NULL DEFAULT '',window_start TIMESTAMPTZ NOT NULL,cpu_ms BIGINT NOT NULL DEFAULT 0 CHECK (cpu_ms >= 0),jobs_completed BIGINT NOT NULL DEFAULT 0 CHECK (jobs_completed >= 0),PRIMARY KEY(tenant_id,project_id,window_start));
CREATE TABLE IF NOT EXISTS forge_resource_fairness (tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id TEXT NOT NULL DEFAULT '',virtual_finish NUMERIC(30,9) NOT NULL DEFAULT 0,last_served_at TIMESTAMPTZ,served_jobs BIGINT NOT NULL DEFAULT 0,queued_jobs BIGINT NOT NULL DEFAULT 0,starvation_count BIGINT NOT NULL DEFAULT 0,deficit NUMERIC(30,9) NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,project_id));
CREATE TABLE IF NOT EXISTS forge_resource_audit (id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,job_id TEXT,reservation_id UUID,action TEXT NOT NULL,outcome TEXT NOT NULL,reason TEXT,plan_version_id TEXT,policy_versions JSONB NOT NULL DEFAULT '{}'::jsonb,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_resource_audit_scope_idx ON forge_resource_audit(tenant_id,project_id,created_at DESC);
CREATE OR REPLACE FUNCTION forge_resource_scope_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE ptenant TEXT; BEGIN IF NEW.project_id IS NOT NULL AND NEW.project_id<>'' THEN SELECT tenant_id INTO ptenant FROM projects WHERE id=NEW.project_id; IF ptenant IS NULL OR ptenant<>NEW.tenant_id THEN RAISE EXCEPTION 'resource tenant/project mismatch'; END IF; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS forge_resource_policy_scope_guard ON forge_resource_policies;
CREATE TRIGGER forge_resource_policy_scope_guard BEFORE INSERT OR UPDATE ON forge_resource_policies FOR EACH ROW EXECUTE FUNCTION forge_resource_scope_guard();
DROP TRIGGER IF EXISTS forge_resource_reservation_scope_guard ON forge_resource_reservations;
CREATE TRIGGER forge_resource_reservation_scope_guard BEFORE INSERT OR UPDATE ON forge_resource_reservations FOR EACH ROW EXECUTE FUNCTION forge_resource_scope_guard();
DROP TRIGGER IF EXISTS forge_resource_fairness_scope_guard ON forge_resource_fairness;
CREATE TRIGGER forge_resource_fairness_scope_guard BEFORE INSERT OR UPDATE ON forge_resource_fairness FOR EACH ROW EXECUTE FUNCTION forge_resource_scope_guard();
DROP TRIGGER IF EXISTS forge_resource_history_scope_guard ON forge_resource_policy_history;
CREATE TRIGGER forge_resource_history_scope_guard BEFORE INSERT OR UPDATE ON forge_resource_policy_history FOR EACH ROW EXECUTE FUNCTION forge_resource_scope_guard();
DROP TRIGGER IF EXISTS forge_resource_audit_scope_guard ON forge_resource_audit;
CREATE TRIGGER forge_resource_audit_scope_guard BEFORE INSERT OR UPDATE ON forge_resource_audit FOR EACH ROW EXECUTE FUNCTION forge_resource_scope_guard();
INSERT INTO forge_resource_policies(scope_type,tenant_id,effective_version,cpu_ms_limit,concurrency_limit,job_count_limit,queue_weight,priority_class,burst_allowance,aging_seconds,max_reservation_seconds,created_by) SELECT 'TENANT',t.id,1,0,100,0,1,100,0,60,3600,'migration' FROM tenants t WHERE NOT EXISTS (SELECT 1 FROM forge_resource_policies p WHERE p.scope_type='TENANT' AND p.tenant_id=t.id AND p.active);
COMMIT;
